class Solution {
public:
    string reformat(string s) {
        int letters = 0, digits = 0;
        for (char c : s) {
            if (c >= '0' && c <= '9') {
                digits++;
            } else {
                letters++;
            }
        }

        if (abs(letters - digits) > 1) {
            return "";
        }

        string res(s.length(), ' ');
        int i = 0, j = 1;

        if (letters <= digits) {
            swap(i, j);
        }

        for (char c : s) {
            if (c >= '0' && c <= '9') {
                res[j] = c;
                j += 2;
            } else {
                res[i] = c;
                i += 2;
            }
        }

        return res;
    }
};
